import{_ as e,o as s,c as r,a5 as a}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"状态持久化","description":"为什么会报 “paths 不存在”？ 你现在项目里 实际装的是 pinia plugin persist（或同系分叉） ， 它给 persist 提供的类型只有： ts 复制编辑 persist: \\\\{ enabled?: boolean strategies?: Persist。","frontmatter":{"title":"状态持久化","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"为什么会报 “paths 不存在”？ 你现在项目里 实际装的是 pinia plugin persist（或同系分叉） ， 它给 persist 提供的类型只有： ts 复制编辑 persist: \\\\{ enabled?: boolean strategies?: Persist。","sidebarWeight":5,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/pinia/状态持久化.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/状态持久化.md","filePath":"posts/Vue系统教程/04-路由与状态管理/状态持久化.md"}'),i={name:"posts/Vue系统教程/04-路由与状态管理/状态持久化.md"};function p(n,t,o,d,g,l){return s(),r("div",null,[...t[0]||(t[0]=[a('<div><h1 id="状态持久化" tabindex="-1">状态持久化 <a class="header-anchor" href="#状态持久化" aria-label="Permalink to &quot;状态持久化&quot;">​</a></h1><blockquote><p>本节目标：理解“状态持久化”的核心思路，并能把它用于实际开发或面试表达。 <strong>为什么会报</strong> <strong>“paths</strong> <strong>不存在”？</strong> 你现在项目里 <strong>实际装的是 pinia-plugin-persist（或同系分叉）</strong>， 它给 persist 提供的类型只有：</p></blockquote><p>ts 复制编辑 persist: { enabled?: boolean strategies?: PersistStrategy[] // ← “paths” 在这里面} 而 <strong>pinia-plugin-persistedstate</strong> 才支持直接写：</p><p>ts 复制编辑 persist: { paths: [...] } 所以 TypeScript 会提示 “paths 不存在”。</p><p><strong>解决方案（二选一）</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>做法</strong></td><td><strong>什么时候选</strong></td><td><strong>写法示例</strong></td></tr><tr><td><strong>A. 继续用</strong> <strong>pinia-plugin-persist</strong></td><td>你项目里已经在用它，改动最小</td><td>ts persist: { enabled: true, strategies: [ { key: &#39;trade-view&#39;, storage: localStorage, paths: [&#39;tabs&#39;, &#39;currentItem&#39;], }, ], }</td></tr><tr><td><strong>B. 换成</strong> <strong>pinia-plugin-persistedstate</strong></td><td>喜欢简单写法 / 官方文档示例</td><td>1) pnpm add pinia-plugin-persistedstate</td></tr></tbody></table><ol start="2"><li>pinia.use(persistedState)</li><li>ts persist: { key: &#39;trade-view&#39;, paths: [&#39;tabs&#39;, &#39;currentItem&#39;] }|</li></ol><p><a href="https://prazdevs.github.io/pinia-plugin-persistedstate/zh/guide/" target="_blank" rel="noreferrer">开始 | Pinia Plugin Persistedstate</a> ==pnpm== ==add pinia-plugin-persistedstate==</p><p>// 全局开启 auto 持久化（不常用的做法） pinia.use( createPersistedState({ auto: true, // ➜ 默认所有 Store 都持久化 key: (id) =&gt; <code>myapp-${id}</code>, }), )</p><p>// 某个 Store 想排除 export const useTempStore = defineStore(&#39;temp&#39;, () =&gt; ({ tmp: 1 }), { persist: false, // 显式关闭 }) &gt; 来自 &lt;<a href="https://prazdevs.github.io/pinia-plugin-persistedstate/zh/guide/" target="_blank" rel="noreferrer">https://prazdevs.github.io/pinia-plugin-persistedstate/zh/guide/</a>&gt;</p></div>',1)])])}const c=e(i,[["render",p]]);export{h as __pageData,c as default};
